import { assertEquals, assertRejects } from "#std/assert";
import {
  collectFrameworkCandidates,
  type FrameworkCandidateArtifactIO,
  type FrameworkCandidateIO,
} from "./framework-candidates.ts";
import { fromFileUrl, join } from "#std/path";
import {
  type FrameworkCandidateCheckReporter,
  runFrameworkCandidatesCheck,
} from "./check-framework-candidates.ts";

const decoder = new TextDecoder();
const CANONICAL_TWO_CANDIDATE_ARTIFACT = `/**
 * Auto-extracted Tailwind CSS candidates from framework components.
 *
 * AUTO-GENERATED by scripts/build/prebundle-client-scripts.ts
 * Do not edit manually — run \`deno task build\` to regenerate.
 * @module
 */

export const FRAMEWORK_CANDIDATES: readonly string[] = [
  "alpha",
  "beta",
];
`;

async function createFrameworkCandidateFixture(
  artifactContents?: string,
): Promise<{ readonly projectRoot: string; readonly artifactPath: string }> {
  const projectRoot = await Deno.makeTempDir({
    prefix: "veryfront-framework-candidate-check-",
  });
  const sourceRoot = join(
    projectRoot,
    "src",
    "react",
    "components",
    "ui",
  );
  const artifactPath = join(projectRoot, "framework-candidates.generated.ts");
  await Deno.mkdir(sourceRoot, { recursive: true });
  await Deno.writeTextFile(join(sourceRoot, "component.tsx"), "alpha beta");
  if (artifactContents !== undefined) {
    await Deno.writeTextFile(artifactPath, artifactContents);
  }
  return { projectRoot, artifactPath };
}

function captureReporter(): {
  readonly reporter: FrameworkCandidateCheckReporter;
  readonly logs: string[];
  readonly errors: string[];
} {
  const logs: string[] = [];
  const errors: string[] = [];
  return {
    reporter: {
      log: (message) => logs.push(message),
      error: (message) => errors.push(message),
    },
    logs,
    errors,
  };
}

Deno.test("importing the framework candidate checker has no CLI side effects", async () => {
  const checkerUrl = new URL(
    "./check-framework-candidates.ts",
    import.meta.url,
  ).href;
  const result = await new Deno.Command(Deno.execPath(), {
    args: [
      "eval",
      "--config=scripts/test.deno.json",
      "--frozen",
      `await import(${JSON.stringify(checkerUrl)}); console.log("imported");`,
    ],
    cwd: fromFileUrl(new URL("../..", import.meta.url)),
    stdout: "piped",
    stderr: "piped",
  }).output();

  assertEquals(result.code, 0);
  assertEquals(decoder.decode(result.stdout), "imported\n");
  assertEquals(decoder.decode(result.stderr), "");
});

Deno.test("framework candidate check accepts only canonical artifact bytes", async () => {
  const fixture = await createFrameworkCandidateFixture(
    CANONICAL_TWO_CANDIDATE_ARTIFACT,
  );
  const output = captureReporter();
  try {
    assertEquals(
      await runFrameworkCandidatesCheck({
        ...fixture,
        reporter: output.reporter,
      }),
      0,
    );
    assertEquals(output.logs, [
      "[framework-candidates] Current (2 candidates).",
    ]);
    assertEquals(output.errors, []);
  } finally {
    await Deno.remove(fixture.projectRoot, { recursive: true });
  }
});

Deno.test("framework candidate check rejects missing tracked artifact", async () => {
  const fixture = await createFrameworkCandidateFixture();
  const output = captureReporter();
  try {
    assertEquals(
      await runFrameworkCandidatesCheck({
        ...fixture,
        reporter: output.reporter,
      }),
      1,
    );
    assertEquals(output.logs, []);
    assertEquals(output.errors, [
      "[framework-candidates] Missing: tracked artifact was not found.",
      "[framework-candidates] Regenerate with `deno task generate`.",
    ]);
  } finally {
    await Deno.remove(fixture.projectRoot, { recursive: true });
  }
});

Deno.test("framework candidate check rejects changed, duplicate, reordered, and noncanonical bytes", async (testContext) => {
  const cases = [
    {
      name: "changed candidate",
      contents: CANONICAL_TWO_CANDIDATE_ARTIFACT.replace(
        '  "alpha",',
        '  "omega",',
      ),
    },
    {
      name: "duplicate candidate",
      contents: CANONICAL_TWO_CANDIDATE_ARTIFACT.replace(
        '  "beta",',
        '  "alpha",\n  "beta",',
      ),
    },
    {
      name: "reordered candidates",
      contents: CANONICAL_TWO_CANDIDATE_ARTIFACT.replace(
        '  "alpha",\n  "beta",',
        '  "beta",\n  "alpha",',
      ),
    },
    {
      name: "noncanonical whitespace",
      contents: CANONICAL_TWO_CANDIDATE_ARTIFACT.replace(
        '  "alpha",',
        '    "alpha",',
      ),
    },
  ] as const;

  for (const testCase of cases) {
    await testContext.step(testCase.name, async () => {
      const fixture = await createFrameworkCandidateFixture(testCase.contents);
      const output = captureReporter();
      try {
        assertEquals(
          await runFrameworkCandidatesCheck({
            ...fixture,
            reporter: output.reporter,
          }),
          1,
        );
        assertEquals(output.logs, []);
        assertEquals(output.errors.length, 2);
        assertEquals(
          output.errors[0]?.startsWith(
            "[framework-candidates] Stale: canonical bytes differ at offset ",
          ),
          true,
        );
        assertEquals(
          output.errors[1],
          "[framework-candidates] Regenerate with `deno task generate`.",
        );
        assertEquals(
          output.errors.every((message) => message.length <= 160),
          true,
        );
      } finally {
        await Deno.remove(fixture.projectRoot, { recursive: true });
      }
    });
  }
});

Deno.test("framework candidate check reads arbitrary additions without executing them", async () => {
  const marker = "__veryfront_framework_artifact_executed__";
  const globalRecord = globalThis as Record<string, unknown>;
  delete globalRecord[marker];
  const fixture = await createFrameworkCandidateFixture(
    `${CANONICAL_TWO_CANDIDATE_ARTIFACT}\nglobalThis[${
      JSON.stringify(marker)
    }] = true;\n`,
  );
  const output = captureReporter();
  try {
    assertEquals(
      await runFrameworkCandidatesCheck({
        ...fixture,
        reporter: output.reporter,
      }),
      1,
    );
    assertEquals(globalRecord[marker], undefined);
    assertEquals(output.logs, []);
    assertEquals(output.errors.length, 2);
  } finally {
    delete globalRecord[marker];
    await Deno.remove(fixture.projectRoot, { recursive: true });
  }
});

Deno.test("framework candidate check propagates operational artifact read failures", async () => {
  const fixture = await createFrameworkCandidateFixture(
    CANONICAL_TWO_CANDIDATE_ARTIFACT,
  );
  const ioError = new Error("framework artifact permission denied");
  const io: FrameworkCandidateArtifactIO = {
    readDir: Deno.readDir,
    readTextFile: Deno.readTextFile,
    readFile: () => Promise.reject(ioError),
  };
  try {
    const received = await assertRejects(
      () =>
        runFrameworkCandidatesCheck({
          ...fixture,
          io,
          reporter: captureReporter().reporter,
        }),
      Error,
      "framework artifact permission denied",
    );
    assertEquals(received, ioError);
  } finally {
    await Deno.remove(fixture.projectRoot, { recursive: true });
  }
});

Deno.test("collectFrameworkCandidates recursively sorts, deduplicates, and excludes tests", async () => {
  const projectRoot = await Deno.makeTempDir({
    prefix: "veryfront-framework-candidates-",
  });
  try {
    const uiRoot = join(projectRoot, "src", "react", "components", "ui");
    const chatRoot = join(
      projectRoot,
      "src",
      "react",
      "components",
      "chat",
      "nested",
    );
    await Deno.mkdir(uiRoot, { recursive: true });
    await Deno.mkdir(chatRoot, { recursive: true });
    await Deno.writeTextFile(join(uiRoot, "first.ts"), "zeta alpha");
    await Deno.writeTextFile(join(chatRoot, "second.tsx"), "beta alpha");
    await Deno.writeTextFile(join(chatRoot, "second.test.tsx"), "ignored-test");
    await Deno.writeTextFile(join(uiRoot, "first.spec.ts"), "ignored-spec");
    await Deno.writeTextFile(join(uiRoot, "ignored.js"), "ignored-extension");
    // `src/react/primitives` is intentionally absent: framework roots are optional.

    assertEquals(await collectFrameworkCandidates(projectRoot), [
      "alpha",
      "beta",
      "zeta",
    ]);
  } finally {
    await Deno.remove(projectRoot, { recursive: true });
  }
});

Deno.test("collectFrameworkCandidates propagates operational traversal errors", async () => {
  const ioError = new Error("framework source permission denied");
  const io: FrameworkCandidateIO = {
    readDir: () => {
      throw ioError;
    },
    readTextFile: Deno.readTextFile,
  };

  const received = await assertRejects(
    () => collectFrameworkCandidates("/project", io),
    Error,
    "framework source permission denied",
  );
  assertEquals(received, ioError);
});

Deno.test("collectFrameworkCandidates does not hide a missing file inside an existing root", async () => {
  const missingSource = new Deno.errors.NotFound(
    "framework source disappeared",
  );
  const io: FrameworkCandidateIO = {
    readDir: async function* () {
      yield {
        name: "disappeared.ts",
        isFile: true,
        isDirectory: false,
        isSymlink: false,
      };
    },
    readTextFile: () => Promise.reject(missingSource),
  };

  const received = await assertRejects(
    () => collectFrameworkCandidates("/project", io),
    Deno.errors.NotFound,
    "framework source disappeared",
  );
  assertEquals(received, missingSource);
});
